contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: params choose caller (as a flag), recipient, and amount to seed into c
    function run(bool callAsOwner, address payable recipient, uint256 seedAmount) public payable {
        // seedAmount will be sent into c from this contract before withdraw attempts
        require(address(this).balance >= seedAmount);

        // record initial observable values
        address ownerBefore = c.owner();
        uint256 balanceCBefore = address(c).balance;
        uint256 balanceThisBefore = address(this).balance;

        // send Ether into c to ensure there is something to withdraw (if seedAmount==0 this is allowed)
        if (seedAmount > 0) {
            // top-level state-changing call on c: use fallback payable by sending value to address(c)
            // since c has a payable fallback, use (bool success, ) low-level call
            (bool ok,) = address(c).call{value: seedAmount}("");
            require(ok);
        }

        // Decide who will call withdrawAll: if callAsOwner==true and ownerBefore == address(this), we are the owner.
        // But the test deployer only controls this contract; the only way this contract can be owner is if c.owner()==address(this).
        // To model both cases, we branch by callAsOwner but must always make the call from this contract (msg.sender==address(this)).

        // perform the withdraw call and capture whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after the call
        address ownerAfter = c.owner();
        uint256 balanceCAfter = address(c).balance;
        uint256 balanceThisAfter = address(this).balance;

        // General rule asserted:
        // - c.owner() never changes by this call
        // - If msg.sender (this contract) was the owner before the call, withdraw must NOT revert and c's balance decreases by at most the previous balance (i.e., becomes 0) and recipient receives the funds (observed as this contract's balance change is >= 0 when recipient != this contract).
        // - If msg.sender was not the owner, the call must revert and c.balance unchanged.
        // Because our test contract is always the caller, callAsOwner parameter selects the intended case but actual owner check uses ownerBefore == address(this).

        // Build the logical assertion:
        // ownerBefore == ownerAfter
        // if ownerBefore == address(this) then reverted == false and balanceCAfter == 0
        // else reverted == true and balanceCAfter == balanceCBefore + seedAmount

        assert(
            ownerBefore == ownerAfter
            && (
                (ownerBefore == address(this))
                    ? (reverted == false && balanceCAfter == 0)
                    : (reverted == true && balanceCAfter == balanceCBefore + seedAmount)
            )
        );
    }

    receive() external payable {}
}

