contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs: owner candidate, recipient, and amount to fund c
    function run(address ownerCandidate, address payable recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Deploy-time owner was set when c was constructed by the test harness; here we only observe it
        address originalOwner = c.owner();

        // Fund contract c with the provided amount so there is a balance to withdraw
        // send Ether to c using its fallback (payable)
        address(c).call{value: amount}("");

        // record balances before calling withdrawAll
        uint256 cBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        bool reverted;
        // Attempt withdrawAll as this contract (msg.sender == address(this)). The contract's owner may or may not equal address(this).
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = recipient.balance;

        // General rule expressed as one assert:
        // If this test contract is the owner recorded in c, the call must not revert and all funds move from c to recipient.
        // If this test contract is not the owner, the call must revert and balances must remain unchanged.
        assert((originalOwner == address(this) && !reverted && cBalanceAfter == 0 && recipientBalanceAfter == recipientBalanceBefore + cBalanceBefore) ||
               (originalOwner != address(this) && reverted && cBalanceAfter == cBalanceBefore && recipientBalanceAfter == recipientBalanceBefore));
    }

    receive() external payable {}
}

