    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: recipient to attempt withdraw to, and amount to fund C with
    function run(address _recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Fund contract c with `amount` ether so there is some balance to withdraw
        (bool ok,) = address(c).call{value: amount}("\x00");
        require(ok);

        // Read owner and balances before the withdraw attempt
        address ownerBefore = c.owner();
        uint256 balanceC_before = address(c).balance;
        uint256 balanceThis_before = address(this).balance;

        // Attempt withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after and owner (owner cannot change in this contract)
        address ownerAfter = c.owner();
        uint256 balanceC_after = address(c).balance;
        uint256 balanceThis_after = address(this).balance;

        // General rule asserted:
        // If the caller (this contract) is the recorded owner, withdrawAll must not revert and must
        // transfer the full previous c balance to the recipient (so c balance becomes 0),
        // else withdrawAll must revert and balances must be unchanged.
        assert(
            (
                msg.sender == ownerBefore &&
                !reverted &&
                ownerBefore == ownerAfter &&
                balanceC_before > 0 &&
                balanceC_after == 0
            ) || (
                !(msg.sender == ownerBefore) &&
                reverted &&
                ownerBefore == ownerAfter &&
                balanceC_after == balanceC_before &&
                balanceThis_after == balanceThis_before
            )
        );
    }

    // allow receiving ether when c transfers out
    receive() external payable {}
}

