    function run(address _recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Fund contract c with `amount` ether so there is some balance to withdraw.
        // Must be a top-level state-changing call on c (we use low-level call to send Ether to fallback),
        // but the constraints require we interact with c only through its public/external surface. Sending Ether
        // via address(c).call is allowed as it invokes c.fallback().
        (bool okFund, ) = address(c).call{value: amount}("");
        require(okFund);

        // Observe before-state
        address ownerBefore = c.owner();
        uint256 balanceC_before = address(c).balance;
        uint256 balanceThis_before = address(this).balance;

        // Attempt withdrawAll and record whether it reverted. This is a top-level call on c.
        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        address ownerAfter = c.owner();
        uint256 balanceC_after = address(c).balance;
        uint256 balanceThis_after = address(this).balance;

        // General rule:
        // - owner() never changes
        // - if this contract was the owner, withdrawAll must not revert and c's balance must become 0 and the recipient must receive the funds (if recipient==this we observe balance increase here)
        // - if this contract was not the owner, withdrawAll must revert and balances remain unchanged
        assert(
            ownerBefore == ownerAfter && (
                (ownerBefore == address(this) && !reverted && balanceC_after == 0 && (
                    // If recipient is this test contract, its balance must increase by the withdrawn amount
                    (_recipient == address(this) ? balanceThis_after == balanceThis_before + balanceC_before : true)
