contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test entry: try withdrawAll with arbitrary recipient and a flag indicating whether to call as owner
    // If asOwner == true, the call should succeed (not revert) and after the call c's balance should be zero.
    // If asOwner == false, the call should revert and c's balance should remain unchanged.
    function run(address recipient, bool asOwner, uint256 fund) public payable {
        require(address(this).balance >= fund);

        // fund the contract c first by sending Ether to it
        if (fund > 0) {
            // send Ether to c via its fallback by transferring from this contract
            payable(address(c)).transfer(fund);
        }

        // read balance before
        uint256 beforeBal = address(c).balance;

        bool reverted;
        if (asOwner) {
            // to simulate calling as owner, we must be the owner recorded in c
            // The constructor of C set owner to some address; we can only be owner if c.owner() == address(this)
            // We attempt the call and record whether it reverted
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }

            // If this contract is owner, withdraw should not revert and should transfer all balance out
            // If not owner, it should revert. We assert the equivalence below.
        } else {
            // call as non-owner (this contract is the caller regardless); still attempt and record revert
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBal = address(c).balance;
