contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs: amount to fund C, the owner address used to construct C,
    // callerIsOwner flag to decide who calls withdrawAll, and recipient to receive withdrawal.
    // The constructor of the checker will have already deployed C with some owner; but per constraints,
    // the checker deploys a fresh C and passes it into our constructor. We must observe behavior for any inputs.
    function run(uint fundAmount, address caller, address recipient, bool callerIsOwner) public payable {
        require(address(this).balance >= fundAmount);

        // Fund C by sending Ether to it. We call its fallback by sending value to address(c).
        (bool sent,) = address(c).call{value: fundAmount}("");
        // funding may succeed or fail depending on fundAmount, but for our property we only consider successful funding
        // so require that the send succeeded to reach meaningful assertions about balances.
        require(sent);

        // Read pre-state: owner and balances
        address preOwner = c.owner();
        uint preBalanceC = address(c).balance;
        uint preBalanceThis = address(this).balance;

        // Decide msg.sender for the withdrawAll call. The tester contract (this) will always be msg.sender for calls into c.
        // To simulate non-owner calls, we only can use the InvMutTest as caller; but we can make c.owner() equal to this contract or not.
        // If callerIsOwner is true, we require that c.owner() == address(this) so that the withdraw call should succeed.
        // If callerIsOwner is false, we require c.owner() != address(this) so the withdraw should revert.
        // Note: these are preconditions on inputs to ensure both branches are reachable by some input choices.
        if (callerIsOwner) {
            require(preOwner == address(this));
        } else {
            require(preOwner != address(this));
        }

        // Perform the withdrawAll call and capture whether it reverted.
        bool reverted;
        try c.withdrawAll(payable(recipient)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state balances
        uint postBalanceC = address(c).balance;
        uint postBalanceThis = address(this).balance;

        // General rule asserted as a single condition:
        // - If caller was owner (preOwner == address(this)), withdrawAll must NOT revert, and all Ether from C moves out (postBalanceC == 0)
        //   and the test contract's balance increases by preBalanceC (postBalanceThis == preBalanceThis + preBalanceC).
        // - If caller was not owner, withdrawAll must revert and balances remain unchanged.
        assert(
            (preOwner == address(this) && !reverted && postBalanceC == 0 && postBalanceThis == preBalanceThis + preBalanceC)
            || (preOwner != address(this) && reverted && postBalanceC == preBalanceC && postBalanceThis == preBalanceThis)
        );
    }

    // Allow receiving Ether when C sends it back to this contract during successful withdraw.
    receive() external payable {}
}

